#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct Block {
    int size;
    struct Block *next;
} Block;

#define HEADER_SIZE sizeof(Block)

Block *free_list = NULL;

void my_init(void *mem, int size) {
    free_list = (Block*)mem;
    free_list->size = size - HEADER_SIZE;
    free_list->next = NULL;
}

void* my_alloc(int size) {
    Block **prev = &free_list;
    Block *cur = free_list;
    while (cur) {
        if (cur->size >= size) {
            if (cur->size > size + HEADER_SIZE + 4) {
                Block *new_block = (Block*)((char*)cur + HEADER_SIZE + size);
                new_block->size = cur->size - size - HEADER_SIZE;
                new_block->next = cur->next;
                cur->size = size;
                cur->next = NULL;
                *prev = new_block;
            } else {
                *prev = cur->next;
            }
            return (char*)cur + HEADER_SIZE;
        }
        prev = &cur->next;
        cur = cur->next;
    }
    return NULL;
}

void my_free(void *ptr) {
    Block *block = (Block*)((char*)ptr - HEADER_SIZE);
    block->next = free_list;
    free_list = block;
}

int main() {
    char mem[1024];
    my_init(mem, 1024);
    int *a = (int*)my_alloc(10 * sizeof(int));
    for (int i = 0; i < 10; i++) a[i] = i * 10;
    for (int i = 0; i < 10; i++) printf("%d ", a[i]);
    printf("\n");
    my_free(a);
    printf("Freed successfully\n");
    return 0;
}
